<template><div class="art-full-height page"><ArtSearchBar v-model="filters" :items="[{label:'手机号',key:'phone',type:'input',props:{placeholder:'请输入手机号'}}]" :show-expand="false" @search="load" @reset="reset"/><ElCard class="art-table-card"><ArtTableHeader :loading="loading" @refresh="load"><template #left><ElButton disabled>按条件批量封禁</ElButton></template></ArtTableHeader><ElTable v-loading="loading" :data="rows"><ElTableColumn type="index" label="序号" width="60"/><ElTableColumn prop="customer_id" label="用户ID"/><ElTableColumn prop="device_type" label="设备类型"/><ElTableColumn prop="brand" label="品牌"/><ElTableColumn prop="device_model" label="设备型号"/><ElTableColumn prop="device_id" label="设备ID" min-width="160"/><ElTableColumn prop="api_base_url" label="API基础地址" min-width="220"/><ElTableColumn prop="system" label="系统"/><ElTableColumn prop="app_version" label="App版本"/><ElTableColumn label="封禁"><template #default="{row}"><ElSwitch :model-value="row.blocked===1" @change="toggle(row)"/></template></ElTableColumn></ElTable></ElCard></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{fetchCustomerDevices,updateCustomerDeviceBlocked,type CustomerDevice}from'@/api/system-manage';defineOptions({name:'UserDevices'});const loading=ref(false),rows=ref<CustomerDevice[]>([]),filters=reactive({phone:''});const load=async()=>{loading.value=true;try{rows.value=await fetchCustomerDevices(filters.phone)}finally{loading.value=false}};const reset=()=>{filters.phone='';load()};const toggle=async(row:CustomerDevice)=>{await updateCustomerDeviceBlocked(row.id,row.blocked===1?2:1);ElMessage.success('设备状态已更新');load()};onMounted(load)</script><style scoped>.page{display:flex;flex-direction:column;gap:12px}.art-table-card{flex:1}</style>